//! 👷️ Real worker preparation retains the admitting source and canonical fault owner before native custody.
use super::*;
use semio_framework_trace::observe_heap_allocations_on_this_thread as observe;
fn stock(row:&serde_json::Value)->RetainedCloneGrant{let s=&row["stock"];RetainedCloneGrant{maximum_items:s["items"].as_u64().unwrap()as usize,maximum_copy_bytes:s["copyBytes"].as_u64().unwrap()as usize,maximum_capacity_bytes:s["capacityBytes"].as_u64().unwrap()as usize,maximum_release_bytes:s["releaseBytes"].as_u64().unwrap()as usize,maximum_depth:s["depth"].as_u64().unwrap()as usize}}
#[test]
fn genuine_worker_preparation_uses_the_admitting_ledger_and_one_current_fuel(){
 let row:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🔣️.json")).unwrap();let bank=stock(&row);let q=RetainedCloneGrant{maximum_items:row["quantum"]["items"].as_u64().unwrap()as usize,..bank};let mut caller=OriginalJobFixtureCaller::admit(OperationId(row["operation"].as_u64().unwrap()),Generation(row["generation"].as_u64().unwrap()),bank,||Some(0),row["stock"]["deadlineUs"].as_u64().unwrap(),row["stock"]["fuel"].as_u64().unwrap());let mut prepared=Some(OriginalWorkerPageReservation::new());let mut born=0;let mut released=0;
 caller.turn(RetainedCloneGrant{maximum_items:0,..q},|cx|{let work=cx.original_work_units_spent();assert!(!prepared.as_mut().unwrap().admit_step(cx)?);assert_eq!(cx.original_work_units_spent(),work);assert!(prepared.as_ref().unwrap().terminal_is_empty());Ok(())}).unwrap();
 let ledger=caller.turn(q,|cx|Ok(cx.payload_authority_identity().0)).unwrap();let mut setup_turns=0;for _ in 0..256{if prepared.as_ref().unwrap().ready(){break;}setup_turns+=1;let loan=1u64<<(setup_turns/8).min(6);caller.turn(q,|cx|cx.with_original_work_loan(loan,cx.deadline_us(),|cx|{let work=cx.original_work_units_spent();let before=cx.retained_progress();let(result,heap)=observe(||prepared.as_mut().unwrap().admit_step(cx));result?;let after=cx.retained_progress();let p=RetainedCloneProgress{copied_items:after.copied_items-before.copied_items,copied_bytes:after.copied_bytes-before.copied_bytes,retained_capacity_bytes:after.retained_capacity_bytes-before.retained_capacity_bytes,released_bytes:after.released_bytes-before.released_bytes};assert!(!heap.overflowed);assert_eq!((heap.requested_bytes,heap.released_bytes),(p.retained_capacity_bytes,p.released_bytes));assert!(cx.original_work_units_spent()-work<=u128::from(loan));born+=heap.requested_bytes;released+=heap.released_bytes;Ok(())})).unwrap();}assert!(prepared.as_ref().unwrap().ready());
 caller.turn(q,|cx|{let p=cx.retained_progress();let work=cx.original_work_units_spent();assert!(prepared.as_mut().unwrap().admit_step(cx)?);assert_eq!(cx.retained_progress(),p);assert_eq!(cx.original_work_units_spent()-work,u128::from(row["cachedWork"].as_u64().unwrap()));Ok(())}).unwrap();
 let mut foreign=OriginalJobFixtureCaller::admit(OperationId(7544),Generation(4),bank,||Some(0),row["stock"]["deadlineUs"].as_u64().unwrap(),row["stock"]["fuel"].as_u64().unwrap());let(result,heap)=observe(||foreign.turn(q,|cx|prepared.as_mut().unwrap().admit_step(cx)));assert!(result.is_err());assert!(!heap.overflowed);assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert!(prepared.as_ref().unwrap().ready());foreign.retire(bank);
 let header=prepared.as_ref().unwrap().fault.as_ref().unwrap().native_header_identity();let mut target=MaybeUninit::<OriginalWorkerPayload>::uninit();caller.turn(q,|cx|{unsafe{OriginalWorkerPayload::initialize_reserved_at(target.as_mut_ptr(),prepared.take().unwrap());}receive_original_retained_work(cx,semio_framework_value::RetainedWorkOutcome::<_,ValueError>{result:Ok(RetainedCloneStep::Complete(RetainedCloneProgress{copied_items:1,..Default::default()})),work:1})?;Ok(())}).unwrap();let mut payload=unsafe{target.assume_init()};assert_eq!(payload.prepared.fault.as_ref().unwrap().native_header_identity(),header);assert_eq!(payload.ledger_identity(),Some(ledger));assert_eq!(serde_json::to_value(std::str::from_utf8(payload.fault().unwrap().single_page().unwrap()).unwrap()).unwrap(),row["fault"]);
 caller.cancel().cancel_now();for _ in 0..row["maximumCloseTurns"].as_u64().unwrap(){if payload.terminal_is_empty(){break;}caller.turn(q,|cx|{let before=cx.retained_progress();let(result,heap)=observe(||payload.close_step(cx));let step=result?;let p=step.progress();let after=cx.retained_progress();let actual=RetainedCloneProgress{copied_items:after.copied_items-before.copied_items,copied_bytes:after.copied_bytes-before.copied_bytes,retained_capacity_bytes:after.retained_capacity_bytes-before.retained_capacity_bytes,released_bytes:after.released_bytes-before.released_bytes};assert_eq!(p,actual);assert!(!heap.overflowed);assert_eq!((heap.requested_bytes,heap.released_bytes),(p.retained_capacity_bytes,p.released_bytes));born+=heap.requested_bytes;released+=heap.released_bytes;Ok(())}).unwrap();}assert!(payload.terminal_is_empty());let(_,heap)=observe(||drop(payload));assert!(!heap.overflowed);assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!(born,released);caller.retire(bank);
}

#[test]
fn genuine_worker_return_place_retains_each_arm_across_foreign_receive_and_paid_close(){
 let row:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🔣️.json")).unwrap();let law:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/return.json")).unwrap();let schema:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/return.schema.json")).unwrap();for(k,v)in law.as_object().unwrap(){assert_eq!(&schema["properties"][k]["const"],v);}let bank=stock(&row);let q=RetainedCloneGrant{maximum_items:1,..bank};
 for arm in law["arms"].as_array().unwrap(){
  let mut caller=OriginalJobFixtureCaller::admit(OperationId(7544),Generation(4),bank,||Some(0),row["stock"]["deadlineUs"].as_u64().unwrap(),row["stock"]["fuel"].as_u64().unwrap());let mut prepared=OriginalWorkerPageReservation::new();
  for _ in 0..row["maximumSetupTurns"].as_u64().unwrap(){if prepared.ready(){break}caller.turn(q,|cx|prepared.admit_step(cx).map(|_|())).unwrap();}assert!(prepared.ready());
  caller.turn(q,|cx|{let claim=prepared.origin.enter_body(cx)?.expect("actual worker return claim");let result=if arm=="continuation"{InteractiveJobStep::Continuation(ValueError::literal(ValueRefusalKind::UnsupportedOwner,"worker original callback cause").into())}else{InteractiveJobStep::from_callback(JobOutcomeBorrow::admit_yield(cx).map_err(OriginalTurnFailure::from))};match claim.finish(cx,result,None){OriginalJobReturn::Outcome(value)=>prepared.returned=Some(value.into_descriptor()),OriginalJobReturn::Continuation(value)=>prepared.pending_continuation=Some(value),_=>panic!("actual worker return arm")};Ok(())}).unwrap();
  let mut foreign=OriginalJobFixtureCaller::admit(OperationId(7544),Generation(4),bank,||Some(0),row["stock"]["deadlineUs"].as_u64().unwrap(),row["stock"]["fuel"].as_u64().unwrap());let before=foreign.fuel_remaining();let(result,heap)=observe(||foreign.turn(q,|cx|prepared.receive_pending(cx)));assert!(result.is_err());assert_eq!(foreign.fuel_remaining(),before);assert!(!heap.overflowed);assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert!(prepared.has_pending_return());foreign.retire(bank);
  caller.turn(q,|cx|{assert!(prepared.receive_pending(cx)?);Ok(())}).unwrap();assert!(!prepared.has_pending_return());if arm=="continuation"{let view=prepared.origin.continuation().unwrap().view();assert_eq!(view.callback.unwrap().primary.message(),"worker original callback cause");}else{assert_eq!(prepared.origin.outcome().unwrap().kind(),JobOutcomeKind::Yield);}
  caller.cancel().cancel_now();for _ in 0..row["maximumCloseTurns"].as_u64().unwrap(){if prepared.terminal_is_empty(){break}caller.turn(q,|cx|prepared.close_step(cx).map(|_|())).unwrap();}assert!(prepared.terminal_is_empty());let(_,heap)=observe(||drop(prepared));assert!(!heap.overflowed);assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));caller.record_born_capacity(semio_framework_job_payload::OriginalReturnEscrowTable::birth_demand().1);caller.retire(bank);
 }
}
